var TIER1_PROVIDERS = /* @__PURE__ */ new Set(["claude", "openai", "mistral", "gemini"]);
var KNOWN_GOOD_LOCAL_MODELS = [
  "llama3.1",
  "llama3.2",
  "llama3.3",
  "qwen2.5",
  "qwen2.5-coder",
  "qwen3",
  "mistral",
  "mixtral",
  "hermes3",
  "command-r",
  "firefunction",
  "functionary",
  "nexusraven",
  "granite3"
];
function getToolTier(modelType, model) {
  if (TIER1_PROVIDERS.has(modelType)) return "tier1";
  if (modelType === "ollama" || modelType === "lmStudio") {
    const lower = model.toLowerCase();
    if (KNOWN_GOOD_LOCAL_MODELS.some((name) => lower.includes(name))) {
      return "tier1";
    }
    return "tier2";
  }
  return "tier2";
}
function effectivePermissionMode(configured, tier) {
  if (tier === "tier2" && configured === "auto-approve") {
    return "ask";
  }
  return configured;
}

