// src/Settings/SettingsView.ts
var SettingsView = class extends import_obsidian30.PluginSettingTab {
  constructor(app, plugin, fab) {
    super(app, plugin);
    this.plugin = plugin;
    this.fab = fab;
  }
  display() {
    const { containerEl } = this;
    containerEl.empty();
    new import_obsidian30.Setting(containerEl).setName("Plugin settings").setDesc("Open the dedicated settings panel with all configuration options.").addButton((button) => {
      button.setButtonText("Open settings");
      button.setCta();
      button.onClick(() => {
        new LLMSettingsModal(this.app, this.plugin, this.fab).open();
      });
    });
    new import_obsidian30.Setting(containerEl).setName("Support development").setDesc("Consider donating to support ongoing development.").addButton((button) => {
      button.setButtonText("Donate");
      button.onClick(() => {
        window.open("https://www.buymeacoffee.com/johnny1093");
      });
    });
    const llmGuy = containerEl.createDiv();
    llmGuy.addClass("llm-icon-wrapper");
    const parser = new DOMParser();
    const svgDoc = parser.parseFromString(LLM_Squad_default, "image/svg+xml");
    const svgElement = svgDoc.documentElement;
    llmGuy.appendChild(svgElement);
    const credits = llmGuy.createDiv({
      attr: { id: "llm-settings-credits" }
    });
    const creditsHeader = credits.createEl("p", {
      text: "LLM plugin",
      attr: { id: "llm-hero-credits" }
    });
    credits.appendChild(creditsHeader);
    const creditsNames = credits.createEl("p", {
      text: "By Johnny\u2728, Ryan Mahoney, and Evan Harris",
      attr: { class: "llm-hero-names llm-text-muted" }
    });
    credits.appendChild(creditsNames);
    const creditsVersion = credits.createSpan({
      text: `v${this.plugin.manifest.version}`,
      attr: { class: "llm-text-muted version" }
    });
    credits.appendChild(creditsVersion);
  }
};

